{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-Kp8mMP/src/parser.js","content":"import { lineError, unknownTaskError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build-graph text format described in the task prompt into a
 * `Map` from task name to `{ cost, deps }`, where `deps` is a `Set` of
 * dependency names. Throws a `CliError` for any malformed line or dangling
 * reference, matching the wording the spec requires.
 */
export function parseGraph(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const tasks = new Map()
  const pendingDeps = new Map()
  const usages = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw lineError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw lineError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw lineError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw lineError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, { cost: parseInt(costStr, 10), deps: new Set() })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw lineError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const [, depName, ...deps] = words
      if (!NAME_RE.test(depName)) {
        throw lineError(`line ${lineNo}: invalid task name ${depName}`)
      }
      for (const dep of deps) {
        if (!NAME_RE.test(dep)) {
          throw lineError(`line ${lineNo}: invalid task name ${dep}`)
        }
      }

      usages.push(depName, ...deps)

      if (!pendingDeps.has(depName)) pendingDeps.set(depName, new Set())
      const set = pendingDeps.get(depName)
      for (const dep of deps) set.add(dep)
    } else {
      throw lineError(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of usages) {
    if (!tasks.has(name)) throw unknownTaskError(name)
  }

  for (const [name, deps] of pendingDeps) {
    const task = tasks.get(name)
    for (const dep of deps) task.deps.add(dep)
  }

  return tasks
}
"}

