/**
 * Runs a depth-first search from each task in ascending name order,
 * walking each task's dependencies in ascending name order, and throws a
 * `CliError` describing the first cycle re-entered this way. Returns
 * nothing when the graph is acyclic.
 */
export function checkForCycle(tasks) {
  const names = [...tasks.keys()].sort()
  const state = new Map()
  const stack = []

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)

    const deps = [...tasks.get(name).deps].sort()
    for (const dep of deps) {
      const depState = state.get(dep)
      if (depState === 'active') {
        const start = stack.indexOf(dep)
        throw cycleError([...stack.slice(start), dep])
      }
      if (depState !== 'done') visit(dep)
    }

    stack.pop()
    state.set(name, 'done')
  }

  for (const name of names) {
    if (!state.has(name)) visit(name)
  }
}

/**
 * Computes, for every task, the wave it sits in (0 for a task with no
 * dependencies, one past the deepest dependency otherwise), its start time
 * (the greatest finish among its dependencies, or 0) and its finish time
 * (start plus cost). Assumes the graph is already known to be acyclic.
 */
export function computeTimings(tasks) {
  const depth = new Map()
  const finish = new Map()

  function depthOf(name) {
    if (depth.has(name)) return depth.get(name)
    const deps = tasks.get(name).deps
    const value = deps.size === 0 ? 0 : 1 + Math.max(...[...deps].map(depthOf))
    depth.set(name, value)
    return value
  }

  function finishOf(name) {
    if (finish.has(name)) return finish.get(name)
    const deps = tasks.get(name).deps
    const start = deps.size === 0 ? 0 : Math.max(...[...deps].map(finishOf))
    const value = start + tasks.get(name).cost
    finish.set(name, value)
    return value
  }

  const timings = new Map()
  for (const name of tasks.keys()) {
    const f = finishOf(name)
    const d = depthOf(name)
    timings.set(name, { start: f - tasks.get(name).cost, finish: f, depth: d })
  }
  return timings
}

/**
 * Groups task names by wave, in ascending name order within each wave and
 * ascending wave order overall.
 */
export function computeWaves(tasks, timings) {
  const waves = []
  for (const name of tasks.keys()) {
    const depth = timings.get(name).depth
    if (!waves[depth]) waves[depth] = []
    waves[depth].push(name)
  }
  for (const wave of waves) {
    if (wave) wave.sort()
  }
  return waves
}

/**
 * The makespan with unlimited workers: the greatest finish time across all
 * tasks, or 0 when there are none.
 */
export function computeTotal(timings) {
  let total = 0
  for (const { finish } of timings.values()) {
    if (finish > total) total = finish
  }
  return total
}
"}

