 * starts at it and walks forward through its dependents (the tasks that
 * depend on it, transitively) down to one nothing depends on.
 */
function computePriorities(tasks) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, { deps }] of tasks) {
    for (const dep of deps) dependents.get(dep).push(name)
  }

  const priority = new Map()
  function priorityOf(name) {
    if (priority.has(name)) return priority.get(name)
    const forward = dependents.get(name)
    const tail = forward.length === 0 ? 0 : Math.max(...forward.map(priorityOf))
    const value = tasks.get(name).cost + tail
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) priorityOf(name)
  return priority
}

/**
 * Simulates the build graph on `workerCount` workers, greedily starting the
 * highest-priority ready task (ties broken by ascending name) on the
 * lowest-index free worker whenever both are available, and otherwise
 * advancing time to the next worker completion. Assumes the graph is
 * already known to be acyclic.
 */
export function pack(tasks, workerCount) {
  const priority = computePriorities(tasks)
  const names = [...tasks.keys()].sort()

  const finish = new Map()
  const started = new Set()
  const freeAt = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])

  let pendingCount = names.length
  let time = 0

  const isReady = (name) => {
    for (const dep of tasks.get(name).deps) {
      const depFinish = finish.get(dep)
      if (depFinish === undefined || depFinish > time) return false
    }
    return true
  }

  while (pendingCount > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let workerIndex = -1
      for (let i = 0; i < workerCount; i++) {
        if (freeAt[i] <= time) {
          workerIndex = i
          break
        }
      }
      if (workerIndex === -1) break

      let best = null
      for (const name of names) {
        if (started.has(name)) continue
        if (!isReady(name)) continue
        if (best === null || priority.get(name) > priority.get(best)) best = name
      }
      if (best === null) break

      const cost = tasks.get(best).cost
      const start = time
      const end = start + cost
      started.add(best)
      pendingCount--
      finish.set(best, end)
      freeAt[workerIndex] = end
      runs[workerIndex].push({ name: best, start, finish: end })
      progressed = true
    }

    if (pendingCount === 0) break

    let next = Infinity
    for (const at of freeAt) {
      if (at > time && at < next) next = at
    }
    time = next
  }

  const makespan = finish.size === 0 ? 0 : Math.max(...finish.values())
  return { runs, makespan }
