/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'
import { CliError, usageError, workersError } from './errors.js'
import { parseGraph } from './parser.js'
import { checkForCycle, computeTimings, computeWaves, computeTotal } from './graph.js'
import { pack } from './pack.js'

const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) throw workersError()
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw usageError()
}

function renderWaves(tasks) {
  const timings = computeTimings(tasks)
  const waves = computeWaves(tasks, timings)
  const lines = []
  for (let i = 0; i < waves.length; i++) {
    if (waves[i]) lines.push(`wave ${i}: ${waves[i].join(' ')}`)
  }
  lines.push(`total ${computeTotal(timings)}`)
  return lines.join('\n') + '\n'
}

function renderExplain(tasks) {
  const timings = computeTimings(tasks)
  const names = [...tasks.keys()].sort()
  const lines = names.map((name) => {
    const { start, finish, depth } = timings.get(name)
    return `${name} start=${start} finish=${finish} depth=${depth}`
  })
  lines.push(`total ${computeTotal(timings)}`)
  return lines.join('\n') + '\n'
}

function renderPack(tasks, workers) {
  const { runs, makespan } = pack(tasks, workers)
  const lines = runs.map((run, i) => {
    const entries = run.map(({ name, start, finish }) => ` ${name}@${start}-${finish}`).join('')
    return `worker ${i}:${entries}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const tasks = parseGraph(input)
  checkForCycle(tasks)

  if (mode === 'waves') return renderWaves(tasks)
  if (mode === 'explain') return renderExplain(tasks)
  return renderPack(tasks, workers)
}

try {
  process.stdout.write(main())
} catch (err) {
  if (err instanceof CliError) {
    process.stderr.write(err.message + '\n')
    process.exit(err.exitCode)
  }
  throw err
}
"}

